'use strict';
let characterPerformances=[];
const performanceReady=workspaceValue('characterPerformances').then(list=>{characterPerformances=Array.isArray(list)?list.filter(validCharacterPerformance).slice(0,30):[]}).catch(()=>{});
function captureCharacterPerformance(o,{name='My performance',start=clipStart(o),end=clipEnd(o)}={}){motionRange(o,start,end);const count=Math.ceil((end-start)*15),frames=[],expressions=[],hands=[];for(let i=0;i<=count;i++){const at=start+(end-start)*i/count,v=stateAt(o,at),expression=expressionAt(o,at),left=handGestureAt(o,'left',at)||'auto',right=handGestureAt(o,'right',at)||'auto';frames.push({t:at-start,v:Object.fromEntries(['x','y','rotation','leg',...motionFields].map(f=>[f,v[f]??0]))});if(expressions.at(-1)?.value!==expression)expressions.push({t:at-start,value:expression});if(hands.at(-1)?.left!==left||hands.at(-1)?.right!==right)hands.push({t:at-start,left,right})}return{id:uid(),version:1,name:name.trim().slice(0,80)||'My performance',duration:end-start,height:o.height||250,frames,expressions,hands,settings:{...(o.ttsVoice?{ttsVoice:o.ttsVoice}:{}),...(o.ttsDelivery?{ttsDelivery:o.ttsDelivery}:{}),mouthStrength:o.mouthStrength??1,expressionBlend:o.expressionBlend??0}}}
function validCharacterPerformance(p){return !!(p&&p.version===1&&typeof p.id==='string'&&typeof p.name==='string'&&p.name.length<=80&&Number.isFinite(p.duration)&&p.duration>=.1&&p.duration<=20&&Number.isFinite(p.height)&&p.height>0&&p.height<=2000&&Array.isArray(p.frames)&&p.frames.length>=2&&p.frames.length<=302&&Math.abs(p.frames[0].t)<.001&&Math.abs(p.frames.at(-1).t-p.duration)<.001&&p.frames.every((k,i)=>k&&Number.isFinite(k.t)&&k.t>=0&&k.t<=p.duration+.001&&(!i||k.t>p.frames[i-1].t)&&k.v&&['x','y','rotation','leg',...motionFields].every(f=>Number.isFinite(k.v[f])&&Math.abs(k.v[f])<=10000))&&Array.isArray(p.expressions)&&p.expressions.length<=302&&p.expressions.every(k=>Number.isFinite(k.t)&&k.t>=0&&k.t<=p.duration&&['happy','curious','surprised','concerned','talk'].includes(k.value))&&Array.isArray(p.hands)&&p.hands.length<=302&&p.hands.every(k=>Number.isFinite(k.t)&&k.t>=0&&k.t<=p.duration&&Object.hasOwn(handGestureNames,k.left)&&Object.hasOwn(handGestureNames,k.right))&&p.settings&&['ttsVoice','ttsDelivery'].every(f=>p.settings[f]===undefined||typeof p.settings[f]==='string'&&p.settings[f].length<=100)&&['mouthStrength','expressionBlend'].every(f=>Number.isFinite(p.settings[f])&&p.settings[f]>=0&&p.settings[f]<=2))}
function buildCharacterPerformance(o,p,{at=time,speed=1,movement=true,voiceSettings=true}={}){if(!validCharacterPerformance(p))throw Error('Invalid performance file.');if(!Number.isFinite(speed)||speed<.25||speed>4)throw Error('Choose a speed between 0.25 and 4.');const end=at+p.duration/speed;motionRange(o,at,end);if(o.lookTargetId||o.pointTargetId)throw Error('Clear the target’s look/point links before applying a combined performance.');if(o.motionPath?.enabled!==false&&o.motionPath?.points?.length&&movement)throw Error('Disable the target’s motion path before applying a performance with travel.');if(o.actionBlocks?.some(b=>b.start<end&&b.start+b.duration>at&&(b.start<at-.001||b.start+b.duration>end+.001)))throw Error('The selected range cuts an existing action. Choose a clear range or remove that action first.');if(current().propInteractions?.some(e=>[e.actorId,e.otherId].includes(o.id)&&e.start<end&&e.start+e.duration>at))throw Error('Apply outside an object interaction so its hand contacts remain connected.');const copy=structuredClone(o),base=stateAt(o,at),origin=p.frames[0].v,size=(o.height||250)/p.height,fields=motionFields.filter(f=>bodyFieldAvailable(o,f)),samples=p.frames.map(k=>({t:Math.round((at+k.t/speed)*1000)/1000,v:Object.fromEntries(fields.map(f=>[f,k.v[f]]))}));copy.actionBlocks=(copy.actionBlocks||[]).filter(b=>b.start>=end||b.start+b.duration<=at);copy.characterLoop='none';copy.lookTargetId=null;copy.pointTargetId=null;copy.footPins=(copy.footPins||[]).filter(pin=>pin.end<=at||pin.start>=end);mergeMotionValues(copy,samples,fields,at,end);const beforeEnd=rawStateAt(o,Math.min(end+.001,clipEnd(o)));if(end<clipEnd(o)-.002){mergeMotionValues(copy,[{t:end+.001,v:stateAt(o,end+.001)}],fields,end+.001,end+.001)}copy.keys=[...copy.keys.filter(k=>k.t<at-.001||k.t>end+.001),...p.frames.map(k=>({t:Math.round((at+k.t/speed)*1000)/1000,v:{...rawStateAt(o,at+k.t/speed),leg:k.v.leg,...(movement?{x:base.x+(k.v.x-origin.x)*size,y:base.y+(k.v.y-origin.y)*size,rotation:base.rotation+k.v.rotation-origin.rotation}:{})}}))].sort((a,b)=>a.t-b.t);if(copy.keys.length>500)throw Error('This performance exceeds the 500-key limit.');if(end<clipEnd(o)-.002)copy.keys.push({t:end+.001,v:beforeEnd});copy.keys.sort((a,b)=>a.t-b.t);copy.ease='linear';for(const [field,source]of [['expressionKeys',p.expressions],['handGestureKeys',p.hands]]){const held=field==='expressionKeys'?{value:expressionAt(o,end)}:{left:handGestureAt(o,'left',end)||'auto',right:handGestureAt(o,'right',end)||'auto'};copy[field]=[...(copy[field]||[]).filter(k=>k.t<at-.001||k.t>end+.001),...source.map(k=>({...structuredClone(k),t:Math.round((at+k.t/speed)*1000)/1000}))];if(end<clipEnd(o)-.002)copy[field].push({t:end+.001,...held});copy[field].sort((a,b)=>a.t-b.t);if(copy[field].length>200)throw Error('This performance would exceed 200 expression or hand keys.')}if(voiceSettings)Object.assign(copy,p.settings);if(!valid({...project,scenes:project.scenes.map(s=>s===current()?{...s,objects:s.objects.map(a=>a.id===o.id?copy:a)}:s)}))throw Error('The performance does not fit this character or scene.');return copy}
document.body.insertAdjacentHTML('beforeend','<dialog id="characterPerformanceDialog"><div class="tool-heading"><h2>Character performances</h2><button id="closeCharacterPerformances">Close</button></div><p class="note">Save body movement, travel, expressions, hand shapes and voice settings together. Reuse with the target character’s own artwork and audio. This replaces animation in the chosen range; a voice recording is not copied.</p><label>Name<input id="performanceName" maxlength="80" value="My performance"></label><div class="rig-tools"><label>Start (s)<input id="performanceStart" type="number" min="0" step="0.1"></label><label>End (s)<input id="performanceEnd" type="number" min="0.1" step="0.1"></label><button id="saveCharacterPerformance">Save range</button></div><label>Apply speed<select id="performanceSpeed"><option value="0.5">0.5×</option><option value="1" selected>1×</option><option value="2">2×</option></select></label><label><input id="performanceTravel" type="checkbox" checked> Include travel</label><label><input id="performanceVoiceSettings" type="checkbox" checked> Include voice settings</label><div id="characterPerformanceList" class="ease-card-list"></div><label class="button">Import performance<input id="importCharacterPerformance" type="file" accept=".json" hidden></label><p id="performanceStatus" class="note" role="status"></p></dialog>');
async function renderCharacterPerformances(){await performanceReady;const list=$('characterPerformanceList');list.replaceChildren();for(const p of characterPerformances){const row=document.createElement('article');row.className='ease-entry';const title=document.createElement('strong');title.textContent=p.name+' · '+p.duration.toFixed(1)+'s';row.append(title,storyButton('Apply',()=>{try{const o=editableCharacter();if(!o)return;const candidate=buildCharacterPerformance(o,p,{at:+$('performanceStart').value,speed:+$('performanceSpeed').value,movement:$('performanceTravel').checked,voiceSettings:$('performanceVoiceSettings').checked});Object.assign(o,candidate);save();render();$('performanceStatus').textContent='Performance applied. Undo restores the previous animation.'}catch(e){$('performanceStatus').textContent=e.message}}),storyButton('Export',()=>download(new Blob([JSON.stringify(p)],{type:'application/json'}),p.name+'.performance.json')),storyButton('Remove',async()=>{const next=characterPerformances.filter(c=>c.id!==p.id);await workspacePut('characterPerformances',next);characterPerformances=next;renderCharacterPerformances()}));list.append(row)}if(!list.children.length)list.innerHTML='<p class="note">No combined performances saved yet. Your existing motion clips, poses, grips and voice takes remain in their own libraries.</p>'}
function openCharacterPerformances(){const o=editableCharacter();if(!o)return;stop();$('performanceStart').value=time;$('performanceEnd').value=Math.min(clipEnd(o),time+2);$('performanceStatus').textContent='Save up to 20 seconds. Applying uses Start above.';renderCharacterPerformances();$('characterPerformanceDialog').showModal()}
$('closeCharacterPerformances').onclick=()=>$('characterPerformanceDialog').close();$('saveCharacterPerformance').onclick=async()=>{try{await performanceReady;if(characterPerformances.length>=30)throw Error('Keep up to 30 performances.');const o=editableCharacter();if(!o)return;const p=captureCharacterPerformance(o,{name:$('performanceName').value,start:+$('performanceStart').value,end:+$('performanceEnd').value});if(!validCharacterPerformance(p))throw Error('This performance contains unsupported expression or pose data.');const next=[...characterPerformances,p];await workspacePut('characterPerformances',next);characterPerformances=next;renderCharacterPerformances();$('performanceStatus').textContent='Combined performance saved on this device.'}catch(e){$('performanceStatus').textContent=e.message}};
$('importCharacterPerformance').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{await performanceReady;if(f.size>2e6)throw Error('Performance files must be smaller than 2 MB.');const p=JSON.parse(await f.text());if(!validCharacterPerformance(p))throw Error('This is not a valid character performance.');if(characterPerformances.length>=30)throw Error('Keep up to 30 performances.');p.id=uid();const next=[...characterPerformances,p];await workspacePut('characterPerformances',next);characterPerformances=next;renderCharacterPerformances()}catch(error){$('performanceStatus').textContent=error.message}};
$('easyAnimationLibrary').append(storyButton('Combined performances',openCharacterPerformances));
const controlsBeforePerformances=renderControls;renderControls=function(){controlsBeforePerformances();if(!isAnimatedCharacter(object()))return;const b=storyButton('Combined performances',openCharacterPerformances);b.id='openCharacterPerformances';b.disabled=!!object().locked;const panel=$('walkCharacterTo')?.closest('details');if(panel)panel.append(b);else $('controls').append(b)};
